    // ── THE KEY TEST: Symbolic sqrt proof by hand ────────────

    /// THE KEY TEST: Hand-construct a proof of sqrt(y²) = y using
    /// the sqrt_square_nonnegative theorem and a hypothesis y ≥ 0.
    ///
    /// Theorem: ∀x, x ≥ 0 → sqrt(x²) = x   (sqrt_square_nonnegative)
    /// Context: hy: y ≥ 0
    /// Goal:    sqrt(y²) = y
    ///
    /// Proof:
    ///   1. Apply sqrt_square_nonnegative with {x → y}
    ///      → premise: y ≥ 0
    ///   2. Use hypothesis hy to discharge the premise
    #[test]
    fn test_check_sqrt_proof_symbolic() {
        reset_fresh_counter();
        let checker = make_checker();

        // Context: y ≥ 0
        let mut ctx = LocalContext::new();
        let hy_id = ctx.add_hypothesis(Proposition::ge(v("y"), num(0.0)));

        // Goal: sqrt(y²) = y
        let goal = Proposition::eq(
            Sqrt(Box::new(Pow(Box::new(v("y")), Box::new(num(2.0))))),
            v("y"),
        );

        let theorem = checker
            .theorem_env
            .get_by_name("sqrt_square_nonnegative")
            .unwrap();

        // Build the substitution: x → y
        let mut subst = Substitution::new();
        subst.insert("x".to_string(), v("y"));

        // Construct the proof
        let proof = Proof::Theorem {
            id: theorem.id,
            subst,
            premise_proofs: vec![
                // Premise proof: y ≥ 0 (from hypothesis)
                Proof::Hypothesis(hy_id),
            ],
        };

        let result = checker.check(&ctx, &proof, &goal);
        if let Err(ref e) = result {
            panic!("Proof check failed: {}", e);
        }
        assert!(result.is_ok());
    }

