    /// Test 17: Theorem with wrong premise proof → should fail
    #[test]
    fn test_check_theorem_wrong_premise() {
        reset_fresh_counter();
        let checker = make_checker();

        let mut ctx = LocalContext::new();
        let hy_id = ctx.add_hypothesis(Proposition::ge(v("y"), num(0.0)));

        // Goal: sqrt(y²) = y
        let goal = Proposition::eq(
            Sqrt(Box::new(Pow(Box::new(v("y")), Box::new(num(2.0))))),
            v("y"),
        );

        let theorem = checker
            .theorem_env
            .get_by_name("sqrt_square_nonnegative")
            .unwrap();

        let mut subst = Substitution::new();
        subst.insert("x".to_string(), v("y"));

        // Wrong premise proof: we provide a hypothesis x = 0 instead of y ≥ 0
        let proof = Proof::Theorem {
            id: theorem.id,
            subst,
            premise_proofs: vec![
                Proof::Hypothesis(hy_id), // This proves y ≥ 0, correct
                                          // Wait, we only have one premise and we provide one proof.
                                          // Let me make it wrong by using a different hypothesis.
            ],
        };

        // Actually, let's make a different test: use a hypothesis that
        // doesn't match the premise. We'll add a hypothesis x = 0 and
        // try to use it to prove y ≥ 0.
        let mut ctx2 = LocalContext::new();
        ctx2.add_hypothesis(Proposition::eq(v("x"), num(0.0)));

        let proof2 = Proof::Theorem {
            id: theorem.id,
            subst: {
                let mut s = Substitution::new();
                s.insert("x".to_string(), v("y"));
                s
            },
            premise_proofs: vec![
                Proof::Hypothesis(HypothesisId(1)), // This proves x = 0, NOT y ≥ 0
            ],
        };

        let result = checker.check(&ctx2, &proof2, &goal);
        assert!(result.is_err());
    }

    /// Test 18: Intro (implication introduction) — P ⊢ Q → ⊢ P → Q
    #[test]
    fn test_check_intro_implies() {
        let checker = make_checker();

        // Start with empty context
        let ctx = LocalContext::new();

        // Build proof: assume P, then use hypothesis to prove P
        let p = Proposition::eq(v("x"), num(0.0));

        let proof = Proof::Intro {
            binder: Binder::Assumption {
                hypothesis_id: HypothesisId(1), // arbitrary, kernel generates its own
                proposition: Box::new(p.clone()),
            },
            body: Box::new(Proof::Hypothesis(HypothesisId(1))),
        };

        let expected = Proposition::implies(p.clone(), p.clone());

        let result = checker.check(&ctx, &proof, &expected);
        if let Err(ref e) = result {
            panic!("Proof check failed: {}", e);
        }
        assert!(result.is_ok());
    }

    /// Test 19: Intro (universal introduction) — ⊢ P(x) → ⊢ ∀x, P(x)
    #[test]
    fn test_check_intro_forall() {
        let checker = make_checker();
        let ctx = LocalContext::new();

        // Prove: ∀x, x = x
        let proof = Proof::Intro {
            binder: Binder::ForAll {
                variable: crate::proposition::shared_var("x"),
            },
            body: Box::new(Proof::Refl(v("x"))),
        };

        let expected = forall_v("x", Proposition::eq(v("x"), v("x")));

        let result = checker.check(&ctx, &proof, &expected);
        if let Err(ref e) = result {
            // The error might just be VarId mismatch even though the display is identical
            let actual = checker.check_inner(&ctx, &proof).unwrap();
            assert_eq!(
                format!("{}", actual),
                format!("{}", expected),
                "Proof check failed: expected {}, got {}",
                expected,
                actual
            );
        }
        assert!(result.is_ok());
    }

    /// Test 20: Intro (universal) with variable appearing in hypothesis → fail
    #[test]
    fn test_check_intro_forall_clash() {
        let checker = make_checker();

        let mut ctx = LocalContext::new();
        ctx.add_hypothesis(Proposition::ge(v("x"), num(0.0))); // x appears in hypothesis

        // Try to prove: ∀x, x = x — but x is free in hypothesis!
        let proof = Proof::Intro {
            binder: Binder::ForAll {
                variable: crate::algebra::Variable::named("x"),
            },
            body: Box::new(Proof::Refl(v("x"))),
        };

        let expected = forall_v("x", Proposition::eq(v("x"), v("x")));

        let result = checker.check(&ctx, &proof, &expected);
        assert!(result.is_err());
        match result.unwrap_err() {
            KernelError::IntroArbitraryClash { .. } => {} // ok
            other => panic!("expected IntroArbitraryClash, got: {:?}", other),
        }
    }

